 "content": "def transform(grid):
    """Replicate the marked 4x4 motif, recolored by each row's left-hand key."""
    h, w = len(grid), len(grid[0])
    sep_color = None
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    if not sep_rows or not sep_cols:
        raise ValueError("expected full-width and full-height panel separators")
    sep_color = grid[sep_rows[0]][0]
    row_bounds = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_bounds.append((start, r))
        start = r + 1
    if start < h:
        row_bounds.append((start, h))
    col_bounds = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_bounds.append((start, c))
        start = c + 1
    if start < w:
        col_bounds.append((start, w))
    if not row_bounds or not col_bounds:
        raise ValueError("no panels")

    # The keyed panels occupy the leftmost column; the separate non-key panel
    # contains the motif that is copied into every panel.
    motif_panel = None
    for r0, r1 in row_bounds:
        for c0, c1 in col_bounds[1:]:
            occupied = [(r-r0, c-c0, grid[r][c])
                        for r in range(r0, r1) for c in range(c0, c1)
                        if grid[r][c] != 0 and grid[r][c] != sep_color]
            if occupied:
                motif_panel = (r1-r0, c1-c0, [(dr, dc) for dr, dc, _ in occupied])
                break
        if motif_panel:
            break
    if motif_panel is None:
        raise ValueError("motif panel not found")
    ph, pw, offsets = motif_panel
    if any(r1-r0 != ph or c1-c0 != pw for r0, r1 in row_bounds for c0, c1 in col_bounds):
        raise ValueError("panels have inconsistent dimensions")

    out = [row[:] for row in grid]
    for band, (r0, r1) in enumerate(row_bounds):
        key_pixels = [grid[r][c] for r in range(r0, r1)
                      for c in range(col_bounds[0][0], col_bounds[0][1])
                      if grid[r][c] not in (0, sep_color)]
        if not key_pixels:
            raise ValueError("key color missing")
        # Use the dominant color in the key panel.
        key = max(set(key_pixels), key=key_pixels.count)
        for c0, c1 in col_bounds:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in offsets:
                out[r0+dr][c0+dc] = key
    return out
